/* ---------- LA OTRA MITAD DEL FICHAJE ----------
   Hasta aquí se negociaba SOLO con el club vendedor: el jugador nunca opinaba,
   la ficha se la ponía calcEco() y todo se cerraba el mismo día sin que el
   calendario se moviera. Estas cinco funciones son las piezas que faltaban, y
   ninguna inventa una escala nueva: se apoyan en ROL_PLANTEL, aceptaRol(),
   pideConRol(), tierPais(), G.conti y el reloj de avanzarUnDia(). */

/* Qué papel le toca a un fichaje según su media FRENTE AL PLANTEL: se ordena
   el plantel por media y se mira dónde caería. Si llega alguien muy superior
   sale 'titular' o 'intocable' sin que haya que acordarse de prometérselo a
   mano. El lector ya existe: chequeoRoles(), satisfaccion() y las peticiones
   del vestuario leen j.rolClub cada semana. */
function rolPorMedia(j,clubId){
  const ovrs=plantelDe(clubId||G.miClub).filter(x=>x.id!==j.id).map(x=>x.ovr).sort((a,b)=>b-a);
  if(!ovrs.length)return 'titular';
  const mejores=ovrs.filter(o=>o>j.ovr).length;                  // cuántos son mejores que él
  const mediaXI=ovrs.slice(0,11).reduce((s,o)=>s+o,0)/Math.min(11,ovrs.length);
  let k;
  if(mejores<=2&&j.ovr>=mediaXI+4)k='intocable';
  else if(mejores<=10)k='titular';
  else if(mejores<=15)k='rotacion';
  else k='suplente';
  /* un chico con techo alto entra como promesa, no de relleno */
  if(j.edad<=21&&j.pot>=j.ovr+8&&(k==='rotacion'||k==='suplente'))k='promesa';
  /* aceptaRol() ya sabe qué papeles se traga cada uno: si el automático no le
     cuadra, se coge el más parecido que sí acepte */
  if(aceptaRol(j,k).ok)return k;
  const i0=ROL_PLANTEL.findIndex(r=>r[0]===k);
  for(let d=1;d<ROL_PLANTEL.length;d++){
    for(const i of[i0-d,i0+d]){
      if(i>=0&&i<ROL_PLANTEL.length&&aceptaRol(j,ROL_PLANTEL[i][0]).ok)return ROL_PLANTEL[i][0];
    }
  }
  return k;
}
/* ¿En qué torneo continental está un club? null si en ninguno. */
function contiDeClub(cid){
  if(!G.conti)return null;
  for(const k of Object.keys(G.conti)){
    const T=G.conti[k];
    if(T&&T.ids&&T.ids.includes(cid))return k;
  }
  return null;
}
/* GANAS DE VENIRSE: nadie baja de escalón por gusto. Compara reputación de
   club, división, torneo continental y país. Devuelve 0..1 y el porqué EN
   TEXTO, porque un número que no se ve en la mesa no cambia ninguna decisión. */
function deseoDeVenir(j){
  const mi=G.clubes[G.miClub],su=j.club?G.clubes[j.club]:null;
  const raz=[];
  let p=0.50;
  if(su){
    const d=mi.rep-su.rep;
    p+=clamp(d*0.020,-0.34,0.26);
    if(d<=-8)raz.push(['mal','Viene de un club más grande: '+su.rep+' de reputación contra tus '+mi.rep]);
    else if(d>=8)raz.push(['bien','Tu club es un salto de categoría para él']);
    if(mi.pais===su.pais&&mi.div>su.div){p-=0.30;raz.push(['mal','Bajaría de división']);}
    else if(mi.pais===su.pais&&mi.div<su.div){p+=0.16;raz.push(['bien','Subiría de división']);}
    if(mi.pais!==su.pais){
      const t=tierPais(mi.pais)-tierPais(su.pais);
      p+=clamp(t*0.35,-0.24,0.18);
      if(t<-0.12)raz.push(['mal','Cambiar de país para ir a una liga menor no le seduce']);
      /* el informe de personalidad ya decía si le costaba mudarse; hasta hoy
         era texto decorativo que no leía nadie */
      if(j.infPers&&/familia/.test(j.infPers.mudanza||'')){p-=0.10;raz.push(['mal','Tiene la familia asentada: mudarse le cuesta']);}
    }
    const cMi=contiDeClub(G.miClub),cSu=contiDeClub(su.id);
    if(cMi&&!cSu){p+=0.14;raz.push(['bien','Le ofreces jugar '+nombreConti(cMi)]);}
    else if(!cMi&&cSu){p-=0.18;raz.push(['mal','Dejaría de jugar '+nombreConti(cSu)]);}
    if(j.pideSalir){p+=0.20;raz.push(['bien','Ya pidió salir de su club']);}
    if(j.moral<40){p+=0.10;raz.push(['bien','Está incómodo donde está']);}
    if(j.años<=1){p+=0.08;raz.push(['bien','Le queda un año de contrato']);}
  }
  /* cuanto mejor es él que el nivel de tu club, más cuesta convencerlo */
  p-=clamp((j.ovr-mi.rep)*0.022,0,0.30);
  if(j.ovr>=mi.rep+6)raz.push(['mal','Está por encima del nivel de tu plantel']);
  p+=(bonusReputacion().fichajes-1);
  if((G.dt.rep||50)>=75)raz.push(['bien','Tu nombre como entrenador pesa en la charla']);
  if(dtTiene('icono'))p+=0.10;
  if(dtTiene('negociador'))p+=0.06;
  const ag=agenteDe(j);
  p+=((G.agConf||{})[ag.n]||0)*0.02;
  if(G.exclusiva===ag.n){p+=0.08;raz.push(['bien','Su agente trabaja en exclusiva contigo']);}
  return{p:clamp(p,0.02,0.97),raz};
}
/* Ficha semanal que pide para firmar. Sale de pideConRol() — la MISMA tabla
   que usa la mesa de renovación — más el recargo por resistencia: cuanto menos
   le apetece el destino, más caro te sale convencerlo. */
function pideFichaje(j,rol,años,des){
  const d=des||deseoDeVenir(j);
  const base=pideConRol(j,rol,años||3);
  const recargo=1+clamp((0.5-d.p)*1.5,-0.15,0.80);
  return Math.max(30,Math.round(base*recargo/10)*10);
}
/* Rellena los campos personales de una mesa ya abierta. Hace falta porque una
   partida guardada CON negociación abierta de la versión anterior no los trae,
   y hacerlo solo en migrar() es justo el error que ya nos costó un saldo en
   NaN: esto se llama antes de USAR la mesa, no al cargar. */
function normNeg(N,j){
  if(!N||!j)return N;
  if(!N.rol)N.rol=rolPorMedia(j);
  if(!N.años)N.años=3;
  if(!N.sueldo)N.sueldo=pideFichaje(j,N.rol,N.años);
  if(N.firma===undefined)N.firma=0;
  if(N.clau===undefined)N.clau=false;
  if(N.pacienciaJ===undefined)N.pacienciaJ=R(3,4);
  if(N.dias===undefined)N.dias=0;
  if(N.espera===undefined)N.espera=0;
  return N;
}
/* Negociar CUESTA DÍAS. Se reutiliza el reloj que ya existe en vez de inventar
   un contador aparte: así el mercado compite de verdad con el resto de la
   semana y con el rival que va detrás del mismo jugador. Si el día que toca
   cae en partido, el reloj se para ahí y la mesa queda abierta esperándote. */
function gastarDiasNegociando(n){
  let dias=0,motivo=null;
  for(let i=0;i<n;i++){
    if(G.fase!=='libre'){motivo=motivo||'Hay un partido en curso';break;}
    motivo=avanzarUnDia();
    dias++;
    if(motivo)break;
  }
  if(motivo&&G.reloj)G.reloj.motivo=motivo;
  return{dias,motivo};
}
/* La respuesta del JUGADOR a lo personal: la segunda puerta que faltaba. El
   dinero compra ganas, pero por debajo del 92% de lo que pide no hay ficha que
   valga y ni se sienta. */
function respuestaDelJugador(N,j){
  const des=deseoDeVenir(j);
  const ac=aceptaRol(j,N.rol);
  if(!ac.ok)return{ok:false,txt:ac.txt,pide:null,des};
  const pide=pideFichaje(j,N.rol,N.años,des);
  if(N.sueldo<Math.round(pide*0.92))
    return{ok:false,pide,des,txt:'Su agente dice que por '+fmt$(N.sueldo)+'/sem no se mueve: pide '+fmt$(pide)+'.'};
  const dinero=clamp((N.sueldo/Math.max(1,pide)-1)*0.9,-0.5,0.35);
  const primaOk=(N.firma||0)>=Math.round(pide*4);       // cuatro semanas de ficha como prima
  const p=clamp(des.p+dinero+(primaOk?0.10:0)+(N.clau?0.08:0)
    +(N.años>=4?0.04:N.años<=1?-0.06:0)+(N.ronda-1)*0.03,0.01,0.97);
  if(RF()<p)return{ok:true,txt:'',pide,des};
  const peor=(des.raz.find(r=>r[0]==='mal')||[null,'No le termina de convencer el proyecto'])[1];
  return{ok:false,pide,des,txt:peor+'. Súbele la ficha, prométele más protagonismo, alarga el contrato o mete prima de fichaje.'};
}
