     por el camino llega el día de partido, el reloj se para ahí y la mesa
     queda abierta esperándote. */
  const gasto=gastarDiasNegociando(N.acuerdoClub?1:R(1,2));
  N.dias=(N.dias||0)+gasto.dias;
