  if(gasto.motivo&&G.fase!=='libre'){
    toast("La reunión se corta: "+gasto.motivo);
    render();guardarLS();return;
  }
  const percibido=valorPercibido(N);
  const ratio=percibido/N.pedido;
  const ag=agenteDe(j);
  let boost=(dtTiene('negociador')?0.08:0)+(dtTiene('icono')?0.06:0)+((G.agConf||{})[ag.n]||0)*0.02
            +(bonusReputacion().fichajes-1)+(G.exclusiva===ag.n?0.06:0);
  const umbral=0.97-boost-(N.ronda-1)*0.04;
  if(N.acuerdoClub||ratio>=umbral){
    if(!N.acuerdoClub){
      N.acuerdoClub=true;
      noticia("🤝 Acuerdo con "+club.nombre,
        "Aceptan tu propuesta por "+j.nombre+". Ahora viene lo difícil: convencerlo a él y a su agente "+ag.n+
        " ("+ag.d+"). Tienes el traspaso cerrado, no el fichaje.");
