       que ya existía en el traspaso, pero por el lado del jugador: alargar la
       mesa se paga, y por eso N.ronda pesa aquí. */
    if(N.rival&&G.clubes[N.rival]&&RF()<clamp(0.08+(N.ronda-1)*0.05,0.04,0.40)){
      const rc=G.clubes[N.rival];
      if(rc.saldo>=N.pedido*0.9){
        const precio=Math.round(N.pedido*(0.95+RF()*0.20)/1000)*1000;
        rc.saldo-=precio;club.saldo+=precio;
        j.club=rc.id;j.moral=clamp(j.moral-6,10,99);delete j.exMio;
