function ofertar(pid,plus){
  const j=G.jug[pid];if(!j)return;
  if(!puedoFichar()){toast("Mercado cerrado (ventanas: sem 1-6 y 18-24)");return;}
  if((G.semRojo||0)>=4){toast("Inhibición concursal: el club en mora no puede fichar");return;}
  const monto=Math.round(j.valor*(plus?1.25:1.0));
  if(monto*1.12>G.saldo){toast("Caja insuficiente: "+fmt$(monto)+" + comisión de agente");return;}
  const club=G.clubes[j.club];
  const _agP=agenteDe(j);
  const _conf=((G.agConf||{})[_agP.n]||0)*0.03;
  const pAcepta=clamp(0.25+(plus?0.35:0.1)+(club.saldo<refCaja(club.rep)*0.35?0.25:0)-(j.ovr>club.rep?0.2:0)
    +(dtTiene('negociador')?0.12:0)+(dtTiene('icono')?0.10:0)+_conf
    +(G.exclusiva===_agP.n?0.12:0)+(bonusReputacion().fichajes-1),0.05,0.96);
  if(RF()<pAcepta){
    mov(-monto,"Fichaje: "+j.nombre+" ("+club.nombre+")");
    const _ag=_agP;
    mov(-Math.round(monto*_ag.com),"Comisión del agente "+_ag.n);
    club.saldo+=monto;
    j.club=G.miClub;j.moral=75;j.años=R(2,4);
    delete j.exMio;
    noticia("Fichaje confirmado",j.nombre+" ("+(j.posE||j.pos)+", "+j.ovr+") firma por "+j.años+" temporadas. Costo: "+fmt$(monto)+".");
    G.pendPresenta=j.id;usarEmergencia();
    armarXI();armarCamarillas();
  }else{
    noticia("Oferta rechazada",club.nombre+" rechazó "+fmt$(monto)+" por "+j.nombre+". Sube la oferta o busca otra opción.");
  }
  render();guardarLS();
}

